  'This syllabus is designed as a rigorous core course in political theory and philosophy. It moves historically from ancient through contemporary thought while repeatedly returning to live questions about authority, liberty, justice, democracy, identity, power, and public life.',
  $pthjson${"slug": "political-theory-philosophy", "title": "Political Theory / Philosophy", "description": "This syllabus is designed as a rigorous core course in political theory and philosophy. It moves historically from ancient through contemporary thought while repeatedly returning to live questions about authority, liberty, justice, democracy, identity, power, and public life.", "topics": [{"id": "1ac35df0-0ebc-49d4-8b71-6b058d0bd24c", "type": "topic", "title": "What Political Theory Is: Questions, Methods, and Normative Argument", "description": "This opening section gives students the toolkit for doing political theory rather than only memorizing thinkers. The focus is on asking better questions, reading arguments carefully, and distinguishing empirical, conceptual, normative, and critical claims.", "children": [{"id": "ab8f7049-3e4e-40b2-ab40-a19a718deb88", "type": "subtopic", "title": "Core Questions and Concepts", "children": [{"id": "1eaaecf6-68e9-4060-aa88-c7d51be8a807", "type": "concept", "title": "Justice, authority, legitimacy, liberty, equality, power, rights, sovereignty, citizenship, democracy"}, {"id": "9761dd8d-da1c-48a7-91e6-1f2b162e58ba", "type": "concept", "title": "What makes political authority legitimate; why obey law; what freedom requires; what equality demands"}, {"id": "aa205d10-b5d3-48f8-9618-ddd904d84d6d", "type": "concept", "title": "State, civil society, market, community, nation, people, class, public, private, and common good"}, {"id": "04c505fd-c111-4e08-b9da-5d1f675ec002", "type": "concept", "title": "Descriptive claims, normative claims, conceptual claims, interpretive claims, and critical claims"}], "description": "Students learn the recurring questions that organize the field."}, {"id": "c2d1a96d-5c54-42b6-9c93-2ad20e233b60", "type": "subtopic", "title": "Methods of Political Theory", "children": [{"id": "7ec71982-9c8a-449e-89df-1ea2610e0e3e", "type": "concept", "title": "Close reading, conceptual analysis, genealogy, ideology critique, reflective equilibrium, thought experiment"}, {"id": "3dc6a942-8d0e-499a-b925-03fb91e37b38", "type": "concept", "title": "Textual context, historical context, authorial purpose, reception, canon formation, and contemporary application"}, {"id": "7c36d381-6d41-45dd-91e2-92a6b3e078d0", "type": "concept", "title": "Primary text, secondary literature, exegesis, reconstruction, objection, reply, and argumentative charity"}, {"id": "0f76370b-b4ec-4108-9acb-a2db69be5f69", "type": "concept", "title": "Analytic political philosophy, history of political thought, critical theory, comparative political theory, and applied theory"}], "description": "Students learn how theorists build arguments from texts, concepts, cases, and institutions."}, {"id": "ff2b7db7-50cd-4c57-819d-3bb1c3bb59ce", "type": "subtopic", "title": "Normative Argument and Evaluation", "children": [{"id": "cf2b85c8-9ef6-49af-af55-3e42edd48e15", "type": "concept", "title": "Premise, conclusion, validity, soundness, counterexample, objection, burden of proof, hidden assumption"}, {"id": "a9533296-2c5f-4c98-97ad-92e6f0fd439a", "type": "concept", "title": "Principle, value conflict, tradeoff, feasibility, institutional design, moral cost, and unintended consequence"}, {"id": "028241fe-a680-4274-a6e9-27033c0b2da6", "type": "concept", "title": "Universalism, particularism, ideal theory, nonideal theory, utopia, realism, and transitional justice"}, {"id": "717f4130-315a-4d91-975e-5bf80808ccc7", "type": "concept", "title": "Writing thesis statements, defining terms, using textual evidence, and responding to objections"}], "description": "Students practice evaluating claims about what political life should be like."}]}, {"id": "eb9db126-4554-4d7f-b6f7-19d5968fd11d", "type": "topic", "title": "Ancient Political Thought: Plato, Aristotle, Citizenship, Virtue, and Regime Types", "description": "Ancient political thought asks what kind of city and character make human flourishing possible. Students study justice, virtue, citizenship, education, and the dangers of corrupt regimes.", "children": [{"id": "6dbccf81-73a5-4ccc-99eb-2ea361612a1e", "type": "subtopic", "title": "Plato, Justice, and the Ideal City", "children": [{"id": "b10c3498-80a1-462e-bc80-1e79afa02ae4", "type": "concept", "title": "Republic, Apology, Crito, philosopher-king, kallipolis, tripartite soul, forms, noble lie"}, {"id": "e6595ebe-4388-452a-b0fe-d253a9cc4388", "type": "concept", "title": "Justice as harmony, specialization, education, censorship, guardians, auxiliaries, producers"}, {"id": "603ac85e-5961-46df-ab6e-cbce6a3a540a", "type": "concept", "title": "Democracy, oligarchy, timocracy, tyranny, appetite, reason, spiritedness, and civic order"}, {"id": "46ac6f46-726d-4ea9-8104-a6c1f5c91dbc", "type": "concept", "title": "Socratic questioning, elenchus, allegory of the cave, and critique of opinion"}], "description": "Students read Plato as a theorist of justice, education, knowledge, and political degeneration."}, {"id": "2d4183a8-fdd3-4367-bddb-a96f4472d8ac", "type": "subtopic", "title": "Aristotle, Virtue, and Constitutionalism", "children": [{"id": "d09de650-b95d-4477-8100-0da0a3132888", "type": "concept", "title": "Politics, Nicomachean Ethics, polis, telos, eudaimonia, virtue, practical wisdom, friendship"}, {"id": "aa738dd7-38f4-4326-bbd1-03210b3c9b1b", "type": "concept", "title": "Citizen, constitution, rule of law, mixed regime, polity, monarchy, aristocracy, democracy, oligarchy, tyranny"}, {"id": "f218309e-6ad5-4300-83a9-6a0bae58f014", "type": "concept", "title": "Distributive justice, corrective justice, natural slavery controversy, household, property, and education"}, {"id": "ed13c6d7-c4b8-4e23-915c-acfde8559d6b", "type": "concept", "title": "Golden mean, habituation, civic virtue, common advantage, and constitutional stability"}], "description": "Students learn Aristotle's account of political life as rooted in human flourishing and practical judgment."}, {"id": "d8796da9-4529-4137-bf2e-7dbb4f511fd1", "type": "subtopic", "title": "Ancient Legacies and Critiques", "children": [{"id": "12ef2f70-2696-4ff7-93d9-bea2c4d1446c", "type": "concept", "title": "Athenian democracy, direct participation, exclusion of women, slaves, foreigners, and noncitizens"}, {"id": "c3090fea-32af-441b-bac4-d4eb0fb91ccb", "type": "concept", "title": "Sophists, rhetoric, nomos versus physis, relativism, skepticism, and public persuasion"}, {"id": "7ba48796-e9b3-4bf0-a01c-6e169f1f9d16", "type": "concept", "title": "Stoicism, cosmopolitanism, natural law, reason, self-rule, and universal moral community"}, {"id": "24d211f7-d4e6-4f91-a3c9-af50a46bfbd6", "type": "concept", "title": "Virtue politics, elite rule, civic education, anti-democratic arguments, and contemporary echoes"}], "description": "Students evaluate the continuing value and limitations of ancient theory."}]}, {"id": "f464665d-65d3-493e-ab90-115d44299421", "type": "topic", "title": "Medieval and Theological Political Thought: Aquinas, Natural Law, Authority, and Conscience", "description": "This section shows how political authority was theorized in relation to divine law, moral order, and conscience. Students examine natural law, just rule, and the limits of obedience.", "children": [{"id": "cfbb950d-fa10-42a9-897e-87853678c402", "type": "subtopic", "title": "Natural Law and Moral Order", "children": [{"id": "ac0d7b5a-c6e2-4924-9a8b-04dc6ca3722b", "type": "concept", "title": "Aquinas, eternal law, natural law, human law, divine law, common good, practical reason"}, {"id": "91c2c239-da19-4f7b-a01f-c8679a9514a2", "type": "concept", "title": "Good, evil, conscience, sin, virtue, prudence, justice, authority, and moral obligation"}, {"id": "a84afd05-4b73-4f36-ad37-34d91a1a1a87", "type": "concept", "title": "Unjust law, legal validity, moral legitimacy, civil disobedience, and higher law traditions"}, {"id": "459f8a4e-5dfa-4601-8cfa-b03bc805afc5", "type": "concept", "title": "Natural rights, natural duties, medieval constitutionalism, and later rights theories"}], "description": "Students learn how natural law links reason, morality, and political authority."}, {"id": "2ed35324-5d0f-4fa5-afb1-d72117c06d6a", "type": "subtopic", "title": "Church, State, and Political Authority", "children": [{"id": "23c12643-f95b-49ea-a143-75cfd82d8703", "type": "concept", "title": "Papal authority, imperial authority, temporal power, spiritual power, two swords doctrine"}, {"id": "3d080597-8cbc-40b4-9439-1574fed353bd", "type": "concept", "title": "Augustine, City of God, earthly city, peace, sin, humility, and political limits"}, {"id": "3d1598ac-2a38-41b5-b715-c133fdc55c72", "type": "concept", "title": "Kingship, tyranny, counsel, consent, corporate bodies, and medieval representation"}, {"id": "5a58b9da-351b-47fb-8b37-c90609bbab5b", "type": "concept", "title": "Conscience, heresy, religious pluralism, toleration, and authority over belief"}], "description": "Students examine conflicts between temporal and spiritual power."}, {"id": "1248006e-bb18-493d-be79-bb512595ee2e", "type": "subtopic", "title": "Continuities into Modern Political Theory", "children": [{"id": "2fc9241f-de7d-4958-a276-b4a6628f84dd", "type": "concept", "title": "Natural law to natural rights, scholastic method, just war, property, charity, and distributive duties"}, {"id": "4edb8082-eee0-4332-be29-5062d08828fd", "type": "concept", "title": "Common good, subsidiarity, moral limits of power, human dignity, and social obligation"}, {"id": "cbae6b8a-4720-45e5-a163-5e4dd86d6117", "type": "concept", "title": "Divine command, reason, secularization, Reformation, religious conflict, and toleration debates"}, {"id": "c6b5b5cd-d1ac-4ae8-8c6a-91b0979d3644", "type": "concept", "title": "Theological roots of liberalism, republicanism, human rights, and public morality"}], "description": "Students see how medieval debates shape later arguments about rights, sovereignty, and law."}]}, {"id": "e86feb72-278f-4c51-8d66-d85eec69b800", "type": "topic", "title": "Machiavelli, Republicanism, Realism, and the Problem of Political Power", "description": "Machiavelli marks a sharp shift toward political realism, statecraft, conflict, and institutional survival. Students ask whether politics has its own logic distinct from ordinary morality.", "children": [{"id": "f40da1de-b7b2-4fc2-8603-0422bb3d651a", "type": "subtopic", "title": "Machiavelli's Prince and Political Necessity", "children": [{"id": "449498a2-7ce0-4d4a-82ce-6d1a4dd98ecd", "type": "concept", "title": "The Prince, virtù, fortuna, necessity, cruelty well-used, appearance, fear, love, arms, and founding"}, {"id": "83f002c1-0fa7-481f-96ae-73de56e9677a", "type": "concept", "title": "Political realism, raison d'etat, emergency, prudence, deception, violence, and moral compromise"}, {"id": "d6036c7e-3a40-4d31-ba53-38d55decd1e7", "type": "concept", "title": "New prince, hereditary prince, military power, popular support, elite ambition, and instability"}, {"id": "a07a0d25-8fa5-45cd-8826-fabdb6ad1f23", "type": "concept", "title": "Ends and means, dirty hands, leadership ethics, and limits of moral idealism"}], "description": "Students analyze political action under insecurity and constraint."}, {"id": "c3fbb766-95b9-4ed2-97dd-50a3655f907b", "type": "subtopic", "title": "Republicanism and Civic Liberty", "children": [{"id": "db551a43-a6d6-499c-9076-a64e04db2f19", "type": "concept", "title": "Discourses, republic, civic virtue, corruption, mixed constitution, citizen militia, liberty as non-domination"}, {"id": "d2d7c81a-e100-4d15-b09c-e5b4e7dc90b5", "type": "concept", "title": "Rome, conflict between people and elites, institutional checks, popular judgment, and public spiritedness"}, {"id": "ae0a631a-8152-4f55-bf3b-08a53656103c", "type": "concept", "title": "Republican freedom, common good, civic participation, rotation in office, and anti-corruption mechanisms"}, {"id": "abbe377f-7d54-411d-9263-4e1408bbd6a0", "type": "concept", "title": "Neo-Roman republicanism, civic humanism, and modern theories of domination"}], "description": "Students compare Machiavelli the realist with Machiavelli the republican."}, {"id": "e34f5240-104d-403d-8616-f86cd738af25", "type": "subtopic", "title": "Power, Conflict, and Political Judgment", "children": [{"id": "d20167d6-5906-4194-9fb9-ffd4a198aa2d", "type": "concept", "title": "Power, coercion, consent, legitimacy, fear, loyalty, trust, reputation, and political survival"}, {"id": "f3664887-c262-405d-ac6b-ae700f7be0bf", "type": "concept", "title": "Realism versus moralism, prudence versus principle, reform versus stability, and leadership responsibility"}, {"id": "f7ea9188-8c78-4597-b7cd-1746035090e8", "type": "concept", "title": "Institutional corruption, faction, emergency powers, populism, and executive action"}, {"id": "fce3441c-b78c-42bf-93c8-e6eec75978c4", "type": "concept", "title": "Case analysis of security, war, crisis leadership, civil conflict, and democratic backsliding"}], "description": "Students learn to evaluate political choices where values collide."}]}, {"id": "5ae37394-7322-4552-b2cd-16d17d724705", "type": "topic", "title": "Social Contract Theory: Hobbes, Locke, Rousseau, Consent, and Legitimacy", "description": "Social contract theory asks why political authority is legitimate and what rational people would agree to under conditions of insecurity, freedom, or inequality.", "children": [{"id": "204bd43f-ed54-4f03-832b-ec0bb076ec4e", "type": "subtopic", "title": "Hobbes: Security, Sovereignty, and the State", "children": [{"id": "1267f00f-a01d-4e4d-a4d2-757bfe24e050", "type": "concept", "title": "Leviathan, state of nature, war of all against all, fear, equality of vulnerability, natural right"}, {"id": "4298e71e-c378-4be1-83ab-2c805b8223f4", "type": "concept", "title": "Laws of nature, covenant, authorization, sovereign, absolutism, security, and civil peace"}, {"id": "da631f28-0510-4a97-a7d9-d668331c9ffc", "type": "concept", "title": "Liberty as silence of the law, obligation, rebellion, punishment, and self-preservation"}, {"id": "87101983-0e43-4805-821d-47d48a9d4b00", "type": "concept", "title": "Anarchy, collective action, security dilemma, and modern state authority"}], "description": "Students learn Hobbes's argument for strong sovereign authority as an answer to disorder."}, {"id": "38009a0a-66ab-4f9b-893f-7a01455a506c", "type": "subtopic", "title": "Locke: Natural Rights, Property, and Limited Government", "children": [{"id": "3d360979-3dfb-4db2-b028-26508ba02b0c", "type": "concept", "title": "Second Treatise, natural rights, life, liberty, property, state of nature, law of nature"}, {"id": "fbe7579f-419f-4380-bcff-27d0cd5cbc05", "type": "concept", "title": "Consent, majority rule, fiduciary trust, legislative supremacy, separation of powers, and prerogative"}, {"id": "5e363d1a-c214-4c9c-9bca-9320425dda7f", "type": "concept", "title": "Labor theory of property, provisos, money, inequality, taxation, and colonial critique"}, {"id": "cd786722-275a-45c0-bc60-0389c52df43b", "type": "concept", "title": "Right of revolution, limited government, toleration, and constitutional liberalism"}], "description": "Students examine liberal constitutionalism through rights, consent, and resistance."}, {"id": "47b3c609-1e12-4d33-9a0d-f16da832405f", "type": "subtopic", "title": "Rousseau: Freedom, Equality, and the General Will", "children": [{"id": "dc1e2675-840e-4d53-9895-1a8eb6e99ede", "type": "concept", "title": "Discourse on Inequality, Social Contract, amour de soi, amour-propre, pity, perfectibility"}, {"id": "6fd2b97a-cd86-4268-9d56-c11adc06d0b6", "type": "concept", "title": "General will, popular sovereignty, lawgiver, civil freedom, moral freedom, forced to be free"}, {"id": "610d7263-f985-4599-9990-90ceb42d95f0", "type": "concept", "title": "Direct democracy, civic religion, corruption, inequality, dependence, and authenticity"}, {"id": "4c643476-0521-4915-bdbb-da170874ffb5", "type": "concept", "title": "Tensions between freedom and conformity, participation and coercion, equality and pluralism"}], "description": "Students analyze Rousseau's critique of inequality and his demanding account of collective self-rule."}]}, {"id": "109414ca-8c6e-4c38-8a0d-d9bb2f80e55b", "type": "topic", "title": "Liberalism and Enlightenment Political Thought: Kant, Mill, Rights, Autonomy, and Liberty", "description": "This section studies liberalism as a family of arguments about autonomy, rights, limited government, public reason, toleration, and individual development.", "children": [{"id": "eed56ba6-8d0c-43bc-b9d8-0e4edbc45dea", "type": "subtopic", "title": "Kant, Autonomy, and Public Reason", "children": [{"id": "0a4abac6-b6ad-4f22-adf5-95c8032e9193", "type": "concept", "title": "Autonomy, dignity, categorical imperative, kingdom of ends, moral law, freedom, rational agency"}, {"id": "c8a157fa-26f1-4ac8-8aef-a8c65aafd275", "type": "concept", "title": "What Is Enlightenment?, public use of reason, private use of reason, immaturity, critique, and progress"}, {"id": "2292954c-6b77-4a8f-9005-f2a3c92e4c3e", "type": "concept", "title": "Right, coercion, republicanism, cosmopolitan right, perpetual peace, and juridical freedom"}, {"id": "cafaf34d-30b6-4a1c-9df9-9031dd17c3d2", "type": "concept", "title": "Respect for persons, consent, public reason, and liberal legitimacy"}], "description": "Students learn Kantian themes of freedom, dignity, moral law, and enlightenment."}, {"id": "052e0b79-05fd-4c5b-bae8-0c9e7228853e", "type": "subtopic", "title": "Mill, Liberty, and Individuality", "children": [{"id": "2f80f6f3-353b-4548-93fd-b004c42cf571", "type": "concept", "title": "On Liberty, harm principle, liberty of thought, liberty of discussion, individuality, experiments in living"}, {"id": "5c98baa5-fbd1-43b7-8b18-9bf13340a7fa", "type": "concept", "title": "Tyranny of the majority, social coercion, paternalism, offense, self-regarding action, other-regarding action"}, {"id": "4f969245-218e-4b21-aae7-2ccaabd520e8", "type": "concept", "title": "Free speech, marketplace of ideas, truth, fallibility, dissent, and democratic culture"}, {"id": "ed1b7c67-c1d6-406a-a7b5-e2a8b0aec839", "type": "concept", "title": "Utilitarian background, higher pleasures, progress, education, and limits of state action"}], "description": "Students examine one of the strongest liberal defenses of free expression and individuality."}, {"id": "796080ef-e60b-45a0-b2b3-dad8d2d50906", "type": "subtopic", "title": "Liberalism's Internal Debates", "children": [{"id": "d99d4ab1-0c36-483b-aac6-4e8e6f459381", "type": "concept", "title": "Classical liberalism, egalitarian liberalism, welfare liberalism, neoliberalism, perfectionist liberalism"}, {"id": "59e296c9-4348-4d4e-9c85-7eb70eab2124", "type": "concept", "title": "Negative liberty, positive liberty, rights, neutrality, toleration, privacy, property, and pluralism"}, {"id": "d99e9b16-b4ef-41e3-99b7-4ad8380f5c58", "type": "concept", "title": "Liberal feminism, liberal nationalism, liberal multiculturalism, and liberal internationalism"}, {"id": "1d3d89ef-5f6a-40df-b97e-525f5eaa6ff4", "type": "concept", "title": "Critiques from communitarianism, conservatism, Marxism, feminism, critical race theory, and postcolonial theory"}], "description": "Students compare different liberal traditions and their critics."}]}, {"id": "9135061a-0e73-4edf-b12c-590d3d395a3b", "type": "topic", "title": "Democratic Theory: Participation, Representation, Deliberation, and Majority Rule", "description": "Democratic theory asks how people can rule themselves under conditions of scale, disagreement, inequality, and institutional complexity.", "children": [{"id": "685a7851-1f0b-40ad-9c7d-2280d4d49a63", "type": "subtopic", "title": "Models of Democracy", "children": [{"id": "5a9412ab-56e9-42af-9c58-d6db62c1bff3", "type": "concept", "title": "Direct democracy, representative democracy, participatory democracy, deliberative democracy, pluralist democracy"}, {"id": "0c3fda61-9a91-4b8d-bb5e-259714064c8e", "type": "concept", "title": "Majoritarian democracy, consensus democracy, elite democracy, republican democracy, agonistic democracy"}, {"id": "4d427d03-a499-4613-b4e9-a5b9c5b85386", "type": "concept", "title": "Popular sovereignty, political equality, accountability, responsiveness, legitimacy, and inclusion"}, {"id": "f8931844-72da-467b-a12d-c755ec29ad89", "type": "concept", "title": "Voting, deliberation, participation, contestation, civil society, and public sphere"}], "description": "Students compare competing accounts of what democracy is for."}, {"id": "4fe443d2-0c3f-40f9-9a0d-0c73646283cd", "type": "subtopic", "title": "Representation and Democratic Institutions", "children": [{"id": "92379ae3-23ae-469e-8e2c-e9ea07ed4aec", "type": "concept", "title": "Delegate, trustee, politico, descriptive representation, substantive representation, symbolic representation"}, {"id": "65ec82a6-c5a5-4f68-b039-db8e06e79bf1", "type": "concept", "title": "Electoral systems, parties, legislatures, courts, bureaucracy, federalism, and constitutional constraints"}, {"id": "63aa4f66-7549-4c04-b9d8-fd277e39e860", "type": "concept", "title": "Mandates, accountability, responsiveness, constituency, public opinion, and political judgment"}, {"id": "86192bf6-630b-4c7a-af5d-b77d175ba1ce", "type": "concept", "title": "Representation of marginalized groups, quotas, districting, campaign finance, and institutional bias"}], "description": "Students analyze what it means for representatives to act for others."}, {"id": "289de624-ed48-4aaa-a44f-fccca250b9e7", "type": "subtopic", "title": "Democratic Problems and Democratic Renewal", "children": [{"id": "01d2b022-ed0e-448b-91d0-ca6345848c0b", "type": "concept", "title": "Majority tyranny, minority rule, polarization, populism, democratic backsliding, corruption, oligarchy"}, {"id": "863891fe-6bac-4893-b3a0-40d3b39a0649", "type": "concept", "title": "Misinformation, apathy, low trust, voter suppression, unequal participation, and institutional veto points"}, {"id": "ffacc93e-f1db-419c-b16d-fb546893d34a", "type": "concept", "title": "Deliberative mini-publics, citizens' assemblies, participatory budgeting, ranked-choice voting, proportional representation"}, {"id": "5b1858a2-bc58-4772-ab95-8ff96903a8b2", "type": "concept", "title": "Civil disagreement, democratic norms, public reason, civic education, and constitutional reform"}], "description": "Students examine threats and reforms in contemporary democracy."}]}, {"id": "f28155e3-a31b-42b5-9741-bbd9b51afd6c", "type": "topic", "title": "Conservatism, Tradition, Community, and Critiques of Rationalist Reform", "description": "Conservatism emphasizes inherited institutions, prudence, order, moral community, and skepticism toward abstract plans. Students study it as a serious theory, not a slogan.", "children": [{"id": "6b453397-9747-4a7e-9612-11e422863a38", "type": "subtopic", "title": "Classical Conservative Arguments", "children": [{"id": "fd819e91-27f3-4ffe-971a-5a36ef6e25e9", "type": "concept", "title": "Edmund Burke, tradition, prescription, prejudice in Burke's sense, inheritance, prudence, and organic society"}, {"id": "e00ac708-a25b-477c-8334-68cb2b129198", "type": "concept", "title": "French Revolution critique, abstract rights, social contract skepticism, reform versus revolution"}, {"id": "310703f3-6990-4ab4-bac1-2b8a906c024a", "type": "concept", "title": "Authority, order, religion, property, community, intermediary institutions, and social continuity"}, {"id": "973b9cf3-bc1e-4ea6-95fa-f038f1b4fe97", "type": "concept", "title": "Human imperfection, unintended consequences, tacit knowledge, and institutional memory"}], "description": "Students learn the philosophical foundations of conservative thought."}, {"id": "d74c2724-4c6b-4e29-88c5-b1867138f4d6", "type": "subtopic", "title": "Modern Conservative Traditions", "children": [{"id": "9118d060-7147-4488-a96d-99e6f895e481", "type": "concept", "title": "Traditionalism, libertarian conservatism, national conservatism, religious conservatism, neoconservatism"}, {"id": "5a4fdfce-82e8-4694-a6fe-f8852339e6c5", "type": "concept", "title": "Market order, family, nation, localism, constitutionalism, anti-communism, and moral authority"}, {"id": "75ad5326-dc2d-410b-a791-634accc529be", "type": "concept", "title": "Fusionism, populist conservatism, law and order, originalism, and administrative-state critique"}, {"id": "52b3c457-7141-486d-a1b3-8e6d27f82a51", "type": "concept", "title": "Tensions between liberty and order, market and community, nationalism and universal rights"}], "description": "Students compare different versions of conservatism that often disagree with one another."}, {"id": "6021d2b7-648d-42d0-a9af-688b5f91d531", "type": "subtopic", "title": "Communitarian and Civic Critiques of Liberalism", "children": [{"id": "5b736058-0b15-4ecf-b955-b883de713363", "type": "concept", "title": "Community, social embeddedness, common good, civic virtue, moral ecology, and associational life"}, {"id": "8a7efc12-93df-4ce4-9a91-c11a6a332e5e", "type": "concept", "title": "Michael Sandel, Alasdair MacIntyre, Charles Taylor, Robert Bellah, and civic republican themes"}, {"id": "adfe66c6-15e0-46bb-97ac-83fc62934f44", "type": "concept", "title": "Atomism, neutrality, individualism, consumerism, social fragmentation, and loss of solidarity"}, {"id": "e8d97231-61cf-49b5-aa88-4e9339858344", "type": "concept", "title": "Pluralism, coercive community, exclusion, conformity, and balancing belonging with rights"}], "description": "Students evaluate arguments that liberalism underestimates belonging, virtue, and shared goods."}]}, {"id": "1ce85152-cb25-4371-9e29-68ed6f38a065", "type": "topic", "title": "Marxism, Socialism, Capitalism, Class, Alienation, and Ideology", "description": "This section studies capitalism as a structure of power and production. Students learn Marxist and socialist concepts used to critique inequality, exploitation, and ideology.", "children": [{"id": "186601f9-9270-4707-8fab-f6a533dcbf40", "type": "subtopic", "title": "Marx's Critique of Capitalism", "children": [{"id": "59d96730-eeb8-4a26-8f3a-f70e3614a48d", "type": "concept", "title": "Historical materialism, mode of production, forces of production, relations of production, base and superstructure"}, {"id": "3c334a71-9d85-4a79-8c48-1b6a79c09ea2", "type": "concept", "title": "Class, bourgeoisie, proletariat, exploitation, surplus value, commodity, labor power, capital accumulation"}, {"id": "b3479156-d2df-47fa-95d0-fd4901611395", "type": "concept", "title": "Alienation, species-being, commodity fetishism, ideology, false consciousness, and class consciousness"}, {"id": "34dc4333-4ada-4399-a56c-eec2b7c4f716", "type": "concept", "title": "Contradiction, crisis, revolution, emancipation, communism, and critique of political economy"}], "description": "Students learn key Marxian concepts and how they fit together."}, {"id": "bc8be3ac-454c-4cd2-86f5-26a665802ad1", "type": "subtopic", "title": "Socialism, Democracy, and Economic Justice", "children": [{"id": "fdc8fdea-484a-4f47-beee-b3894b67247a", "type": "concept", "title": "Utopian socialism, scientific socialism, democratic socialism, social democracy, communism, anarchism"}, {"id": "2e25bfd9-1b49-43f8-ac11-e3cecf045bbf", "type": "concept", "title": "Worker control, public ownership, cooperative ownership, planning, redistribution, welfare state, and decommodification"}, {"id": "26b41bdd-b329-4908-a69f-d52c9d642444", "type": "concept", "title": "Class politics, labor movements, unions, party organization, revolution versus reform"}, {"id": "2b44e181-814b-4056-ae2b-46d47485623c", "type": "concept", "title": "Authoritarian socialism, bureaucratization, market socialism, mixed economies, and democratic accountability"}], "description": "Students compare socialist traditions and their democratic aspirations or dangers."}, {"id": "8ed93e3a-2ffd-46fc-8c9b-5089d5e5cb2e", "type": "subtopic", "title": "Marxist, Neo-Marxist, and Critical Extensions", "children": [{"id": "11f68f24-67f9-4c5e-b7cc-a981b5a8ae12", "type": "concept", "title": "Gramsci, hegemony, civil society, organic intellectuals, war of position, consent"}, {"id": "00ee2452-6c01-474a-bec7-f0e5cb5a4fb1", "type": "concept", "title": "Frankfurt School, critical theory, culture industry, instrumental reason, one-dimensional society"}, {"id": "7af306cc-cfeb-4c08-a4bc-157affe9fcea", "type": "concept", "title": "Ideology critique, reification, racial capitalism, social reproduction theory, and dependency theory"}, {"id": "0c2e06e2-6146-4df5-80ce-f5d32a3eead8", "type": "concept", "title": "Contemporary debates on neoliberalism, austerity, platform capitalism, precarity, and inequality"}], "description": "Students see how Marxist analysis evolved into broader theories of domination and culture."}]}, {"id": "bbacbd8f-4220-40a6-bc49-b3d0f803e2a5", "type": "topic", "title": "Theories of Justice: Rawls, Nozick, Distributive Justice, Equality, and Desert", "description": "Justice theory asks how benefits, burdens, rights, opportunities, and recognition should be distributed. Students compare powerful frameworks that lead to different policy conclusions.", "children": [{"id": "08241da9-d69b-4619-aa2a-9fd0e9e29582", "type": "subtopic", "title": "Rawls and Justice as Fairness", "children": [{"id": "7ca5acb2-9780-4db0-a5ff-786972a76a3f", "type": "concept", "title": "Original position, veil of ignorance, parties, primary goods, basic structure, fair terms of cooperation"}, {"id": "1220272e-5822-4b6e-9391-3ebd606d9fcd", "type": "concept", "title": "Equal basic liberties, fair equality of opportunity, difference principle, lexical priority"}, {"id": "4c13a7d4-328c-4bfe-90b7-05950e192997", "type": "concept", "title": "Reflective equilibrium, public reason, overlapping consensus, political liberalism, reasonable pluralism"}, {"id": "73cabb3a-3d4d-4e3a-ade1-b964d5e0646c", "type": "concept", "title": "Critiques of ideal theory, disability, race, gender, global justice, and property-owning democracy"}], "description": "Students learn Rawls's influential reconstruction of social contract theory."}, {"id": "0c73c2f3-eada-49a6-8b98-859fcc52da71", "type": "subtopic", "title": "Nozick, Libertarianism, and Entitlement", "children": [{"id": "ccf1bb85-b5b5-4cb0-91b0-acfca8e796d5", "type": "concept", "title": "Anarchy, State, and Utopia, minimal state, self-ownership, side constraints, rights as trumps"}, {"id": "eae661f5-e2c6-4a95-a704-5706f9059db4", "type": "concept", "title": "Entitlement theory, justice in acquisition, justice in transfer, rectification, patterned principles"}, {"id": "a0025657-01f3-42db-902f-5fa844888548", "type": "concept", "title": "Wilt Chamberlain example, taxation as forced labor claim, voluntary exchange, and historical justice"}, {"id": "a2b4dd3b-c7d1-4d6e-a190-b6293e9674aa", "type": "concept", "title": "Critiques concerning inheritance, unequal starting points, coercion, public goods, and structural domination"}], "description": "Students examine a strong challenge to redistributive justice."}, {"id": "77da53c0-2a7b-41cb-8bf9-17f0993153b5", "type": "subtopic", "title": "Equality, Desert, Need, and Capability", "children": [{"id": "c5ae94f1-beb0-4775-a2f0-488f759ceb08", "type": "concept", "title": "Equality of outcome, equality of opportunity, luck egalitarianism, prioritarianism, sufficientarianism"}, {"id": "1ff914a5-d465-49b8-a7c9-bdb174b94378", "type": "concept", "title": "Desert, merit, contribution, effort, need, welfare, resources, capabilities, and recognition"}, {"id": "33dc0091-e07a-476d-a499-b3410412c874", "type": "concept", "title": "Amartya Sen, Martha Nussbaum, capability approach, human development, functioning, and agency"}, {"id": "e30ffc48-3973-4aab-83c0-c3894b6728b6", "type": "concept", "title": "Policy cases: education, health, housing, taxation, basic income, disability, and climate burdens"}], "description": "Students compare alternative distributive principles and what each reveals."}]}, {"id": "23effbdf-6edc-4bad-b048-6c7a81fc6685", "type": "topic", "title": "Power, Domination, Freedom, and Critical Theory", "description": "This section pushes beyond formal legal freedom to ask how power operates through institutions, norms, knowledge, identity, and everyday life.", "children": [{"id": "4090e04a-0890-4a9c-87a6-2a791eaef792", "type": "subtopic", "title": "Power and Domination", "children": [{"id": "0f7dbeaa-ae42-4c53-9f4d-26d1f0212562", "type": "concept", "title": "Power over, power to, power with, domination, coercion, authority, influence, manipulation"}, {"id": "18234072-f9d4-46fb-b6dd-d0b80a7e883d", "type": "concept", "title": "Steven Lukes, three dimensions of power, agenda control, preference shaping, and latent conflict"}, {"id": "610a092c-bd72-4dce-8c6f-311f175f3e22", "type": "concept", "title": "Republican freedom as non-domination, arbitrary power, dependency, vulnerability, and civic status"}, {"id": "e424c42e-fc33-4ab8-a1e4-3baa46ea295e", "type": "concept", "title": "Structural power, institutional power, discursive power, and social power"}], "description": "Students distinguish forms of power that are visible, hidden, structural, and internalized."}, {"id": "2b62fa5a-2f73-42ee-8a26-9250d3aa8f59", "type": "subtopic", "title": "Critical Theory and Ideology Critique", "children": [{"id": "f4cfdeeb-0657-4da1-ac76-fab2f404831b", "type": "concept", "title": "Frankfurt School, Horkheimer, Adorno, Marcuse, Habermas, critical theory, traditional theory"}, {"id": "31129614-c396-4241-b4b4-795b3750d9e5", "type": "concept", "title": "Ideology, reification, alienation, culture industry, instrumental reason, communicative action, lifeworld"}, {"id": "84c0d7d8-23c8-44c9-b267-5b75bc3b8f5f", "type": "concept", "title": "Emancipation, critique, false necessity, domination, recognition, and democratic communication"}, {"id": "d77c79e3-3398-442a-bdfd-14a19916108b", "type": "concept", "title": "Public sphere, deliberation, legitimacy crisis, technocracy, and distorted communication"}], "description": "Students learn how critical theory connects knowledge, domination, emancipation, and social critique."}, {"id": "2eabfb9e-2d22-4990-82f0-96def8e95bb0", "type": "subtopic", "title": "Foucault, Discipline, and Governmentality", "children": [{"id": "0e8e09ae-6735-4f71-9d71-bc7e45179d21", "type": "concept", "title": "Discipline, surveillance, panopticon, normalization, biopower, governmentality, subject formation"}, {"id": "323a7687-4589-4b93-af2f-55c60980f472", "type": "concept", "title": "Power/knowledge, discourse, genealogy, regime of truth, docile bodies, and expert authority"}, {"id": "6f7be8c4-7b0e-4e43-a3e9-25896b4524a7", "type": "concept", "title": "Prisons, medicine, sexuality, schooling, statistics, bureaucracy, and modern administration"}, {"id": "b6669e3e-2c26-411d-a397-95b4522aa31f", "type": "concept", "title": "Resistance, freedom, critique, self-making, and debates over normativity"}], "description": "Students examine power as productive, dispersed, and tied to knowledge."}]}, {"id": "ab57a9cf-4389-4cbc-97ec-bdccf7e18a66", "type": "topic", "title": "Feminist, Race, Postcolonial, and Intersectional Political Theory", "description": "This section shows how political theory changes when marginalized experiences and structures of domination are placed at the center of analysis.", "children": [{"id": "79e0d057-275c-446d-86e3-9b6e179eb936", "type": "subtopic", "title": "Feminist Political Theory", "children": [{"id": "1154ab79-8d35-4b94-b336-398fff2fad15", "type": "concept", "title": "Liberal feminism, radical feminism, socialist feminism, care ethics, difference feminism, queer feminism"}, {"id": "b9409f05-a0d5-4765-91bc-4735831783ac", "type": "concept", "title": "Public/private divide, patriarchy, gendered labor, reproductive labor, embodiment, autonomy, and dependency"}, {"id": "7589e73f-ad80-4974-97a7-d3e751a1dcf9", "type": "concept", "title": "Mary Wollstonecraft, Simone de Beauvoir, Catharine MacKinnon, bell hooks, Judith Butler, Iris Marion Young"}, {"id": "61a204b1-c4ff-4481-ac36-c73cc3a1745c", "type": "concept", "title": "Care, vulnerability, domination, consent, sexual politics, family, work, and representation"}], "description": "Students study critiques of gendered power in public and private life."}, {"id": "2ddac198-3c0c-4b25-b275-60c3ea9ac4aa", "type": "subtopic", "title": "Race, Racial Justice, and Critical Race Theory", "children": [{"id": "a441f658-e8ea-4b24-8085-57c8e3e3c7f1", "type": "concept", "title": "Race, racism, racialization, white supremacy, racial capitalism, interest convergence, structural racism"}, {"id": "fefd7b9c-df8d-444c-b4bd-5f05ee3b54ff", "type": "concept", "title": "W. E. B. Du Bois, Frantz Fanon, Charles Mills, Angela Davis, Kimberle Crenshaw, Derrick Bell"}, {"id": "9778a9af-ff08-4933-bbda-c88b9d33a499", "type": "concept", "title": "The Racial Contract, double consciousness, colonial violence, prison abolition, and civil rights critique"}, {"id": "3487299c-2b85-440b-aaff-105226ea0ff3", "type": "concept", "title": "Colorblindness, equal protection, reparations, voting rights, policing, housing, and educational inequality"}], "description": "Students learn how race structures citizenship, law, property, recognition, and state power."}, {"id": "ea0901c8-7b80-4177-8edc-e2f038ad463b", "type": "subtopic", "title": "Postcolonial and Intersectional Theory", "children": [{"id": "e012a881-56e5-4e90-a3c9-9bd6ebdea346", "type": "concept", "title": "Colonialism, imperialism, decolonization, Orientalism, subaltern, hybridity, settler colonialism"}, {"id": "0882891b-4d77-48af-85bd-ccdfa8ec22e0", "type": "concept", "title": "Edward Said, Gayatri Spivak, Homi Bhabha, Achille Mbembe, Linda Tuhiwai Smith"}, {"id": "6544c9cd-28d1-4ec1-ae46-cfdad758e131", "type": "concept", "title": "Intersectionality, matrix of domination, gender, race, class, sexuality, disability, nationality, and migration status"}, {"id": "2d7083e7-c27b-458c-8fc8-bfff15bdfa9b", "type": "concept", "title": "Epistemic injustice, voice, representation, land, sovereignty, borders, and global inequality"}], "description": "Students analyze how empire, identity, and overlapping structures of power shape political life."}]}, {"id": "10dcf733-b8ea-45c8-95ae-cfb5d573fa0c", "type": "topic", "title": "Identity, Recognition, Multiculturalism, Nationalism, and Belonging", "description": "Political communities decide who belongs, whose identities receive recognition, and how difference should be governed. Students examine membership, culture, nationalism, and pluralism.", "children": [{"id": "59663633-32c6-470e-bb04-6ad0e79d2379", "type": "subtopic", "title": "Recognition and Identity Politics", "children": [{"id": "7caf2031-038a-4682-9aa3-5e38e35067ae", "type": "concept", "title": "Recognition, misrecognition, identity, dignity, status, respect, esteem, and social membership"}, {"id": "897f874c-7198-4cd5-a9d6-bd9cfc43ae90", "type": "concept", "title": "Charles Taylor, Axel Honneth, Nancy Fraser, redistribution-recognition debate, and participatory parity"}, {"id": "2a967f35-592a-4fa0-8c33-a1c517062b62", "type": "concept", "title": "Identity politics, group rights, symbolic injury, cultural recognition, and political voice"}, {"id": "ee713ba4-8c45-41f3-95e3-e2d8a75e5144", "type": "concept", "title": "Critiques: essentialism, fragmentation, resentment, class displacement, and universalism"}], "description": "Students learn why recognition can be a matter of justice rather than mere symbolism."}, {"id": "3a3919ec-5e6f-45b2-a464-a5809dcb7543", "type": "subtopic", "title": "Multiculturalism and Pluralism", "children": [{"id": "38ab7c7d-7ae8-40e8-8885-deb1792b97de", "type": "concept", "title": "Multiculturalism, pluralism, assimilation, integration, accommodation, toleration, secularism"}, {"id": "803548db-9db0-4719-acab-2565adb941d1", "type": "concept", "title": "Will Kymlicka, minority rights, polyethnic rights, self-government rights, language rights"}, {"id": "207412be-5a30-4734-bc35-d9fda6d12c29", "type": "concept", "title": "Religious freedom, cultural practices, liberal neutrality, group autonomy, and internal minorities"}, {"id": "da7b5126-b731-4543-b622-df374764ba8d", "type": "concept", "title": "Headscarves, education, language policy, Indigenous rights, immigration, and civic integration"}], "description": "Students compare approaches to governing cultural, religious, and linguistic diversity."}, {"id": "0e33cd20-1ea2-47e3-b28b-aa400612b7a7", "type": "subtopic", "title": "Nationalism, Citizenship, and Borders", "children": [{"id": "49b1f127-721c-4b98-9919-7587986aaf29", "type": "concept", "title": "Nation, state, nation-state, peoplehood, patriotism, nationalism, civic nationalism, ethnic nationalism"}, {"id": "d77fdfc9-320b-4a4c-8bc2-1968e0b1e36c", "type": "concept", "title": "Citizenship, birthright citizenship, naturalization, migration, refugees, statelessness, diaspora"}, {"id": "5910ebed-dacd-462e-9ba9-cee2d2239965", "type": "concept", "title": "Self-determination, sovereignty, secession, Indigenous sovereignty, and settler colonialism"}, {"id": "3835a30d-37fb-4bc0-9081-03c5d615c653", "type": "concept", "title": "Cosmopolitanism, open borders, border control, democratic membership, and global obligations"}], "description": "Students evaluate the moral and political claims of nationhood and membership."}]}, {"id": "eb6d7c4f-4806-4a94-985c-6cf36fc3524e", "type": "topic", "title": "Rights, Law, Civil Disobedience, Violence, and Political Obligation", "description": "This section asks why law binds us, when resistance is justified, and how rights claims interact with coercion, punishment, and protest.", "children": [{"id": "fe60cc32-ab7b-4674-b34c-67b68982fd46", "type": "subtopic", "title": "Political Obligation and Legitimacy", "children": [{"id": "cdf6540d-a02b-492f-8083-ab87272b30af", "type": "concept", "title": "Consent, fair play, gratitude, associative obligation, natural duty of justice, and public goods"}, {"id": "4f9eb8ce-afc4-447a-a45c-56b985e1fce2", "type": "concept", "title": "Legitimacy, authority, coercion, obligation, compliance, allegiance, and civic duty"}, {"id": "ed0c26e2-7a71-434e-be81-10acbc84a2ff", "type": "concept", "title": "Anarchism, philosophical anarchism, state legitimacy, and limits of consent theory"}, {"id": "e2a63ba5-5717-4bc5-9df8-162f22b66307", "type": "concept", "title": "Cases: unjust laws, taxation, conscription, jury duty, public health mandates, and emergency rules"}], "description": "Students evaluate arguments for obeying law and supporting institutions."}, {"id": "97f621db-ce6b-4655-a5bc-2daa0586e788", "type": "subtopic", "title": "Rights, Law, and Civil Disobedience", "children": [{"id": "ab7f3bbd-4b39-46ed-8744-f7c58739a448", "type": "concept", "title": "Civil disobedience, conscientious refusal, protest, direct action, nonviolence, publicity, willingness to accept punishment"}, {"id": "851a5990-3792-437f-b183-1a378fd4d9a8", "type": "concept", "title": "Thoreau, Gandhi, Martin Luther King Jr., Rawls, Habermas, and contemporary protest theory"}, {"id": "6013eb6d-84bc-4aea-ba23-4731eda971e5", "type": "concept", "title": "Letter from Birmingham Jail, unjust law, natural law, democratic appeal, and moral witness"}, {"id": "11441767-232a-45af-9ff5-f54db33db94e", "type": "concept", "title": "Whistleblowing, sanctuary, climate protest, digital protest, and limits of civility"}], "description": "Students study principled lawbreaking as a democratic and moral practice."}, {"id": "8a3d8ac5-b498-4ddb-9a96-8b6316e1b49b", "type": "subtopic", "title": "Violence, Punishment, War, and Revolution", "children": [{"id": "08fc1b34-1ce9-4c1d-b330-0bf7faf64761", "type": "concept", "title": "State violence, police power, punishment, deterrence, retribution, rehabilitation, restorative justice"}, {"id": "912daab7-4185-4197-9292-46025d420921", "type": "concept", "title": "Just war, pacifism, self-defense, revolution, terrorism, insurgency, humanitarian intervention"}, {"id": "fb544ce1-bbc2-413a-991c-cafba71bbecf", "type": "concept", "title": "Legitimate force, proportionality, necessity, discrimination, last resort, and collective responsibility"}, {"id": "4c92edc0-e0e0-49d0-a5d1-49e4db0423ff", "type": "concept", "title": "Abolition, prison reform, transitional justice, amnesty, reparations, and reconciliation"}], "description": "Students examine when coercive or violent action is defended or condemned."}]}, {"id": "ac438023-8d9f-463b-89cd-af67d5f40964", "type": "topic", "title": "Contemporary Applied Debates: Technology, Climate, Markets, Borders, Public Health, and Global Justice", "description": "Political theory becomes practical when applied to current dilemmas. Students use concepts from the course to reason about urgent public problems.", "children": [{"id": "028e7f0d-0c09-4039-86cd-aa881db6ad3b", "type": "subtopic", "title": "Technology, Algorithms, and Democratic Power", "children": [{"id": "3f7e75a6-655c-4ec5-8b27-52b25de91e37", "type": "concept", "title": "Algorithmic governance, surveillance, privacy, platform power, artificial intelligence, automation, data justice"}, {"id": "035e72ad-a14a-4d46-b642-e672bff10303", "type": "concept", "title": "Bias, discrimination, opacity, accountability, explainability, due process, and predictive systems"}, {"id": "712088bc-7df5-4dd3-a1b1-dc5cac6d7bac", "type": "concept", "title": "Free speech online, content moderation, misinformation, digital public sphere, and platform regulation"}, {"id": "ea1caa82-d4b5-4f47-827c-bbe8bec7d2a7", "type": "concept", "title": "Techno-solutionism, democratic oversight, digital rights, and civic design"}], "description": "Students analyze digital systems as political institutions that shape freedom and equality."}, {"id": "fd871081-8e46-4058-b317-257d4ece5e25", "type": "subtopic", "title": "Climate, Environment, and Intergenerational Justice", "children": [{"id": "e467500e-2184-4ee2-b677-a6b3a6730caf", "type": "concept", "title": "Climate justice, environmental justice, intergenerational justice, sustainability, adaptation, mitigation"}, {"id": "1550ac5a-5a09-45f8-9f51-10d784f33a36", "type": "concept", "title": "Common but differentiated responsibilities, loss and damage, ecological citizenship, and green republicanism"}, {"id": "df1262f6-b216-4323-ab4d-e91b32470bdd", "type": "concept", "title": "Rights of nature, animal ethics, land ethics, Indigenous ecological knowledge, and stewardship"}, {"id": "402a6973-a63a-434d-81da-264e2bfdf71a", "type": "concept", "title": "Carbon pricing, just transition, climate migration, sacrifice zones, and global inequality"}], "description": "Students consider duties to future people, nonhuman life, and vulnerable communities."}, {"id": "d4e956ee-ac5d-4d99-9c3f-0eaf1ab683fe", "type": "subtopic", "title": "Markets, Borders, Health, and Global Justice", "children": [{"id": "66be3928-72bf-4dc8-a9f6-a74e74130758", "type": "concept", "title": "Global distributive justice, cosmopolitanism, statism, human rights, humanitarianism, and development"}, {"id": "167e2e4e-51e8-463e-8231-beb5494cf41f", "type": "concept", "title": "Markets, commodification, labor exploitation, wealth inequality, basic income, and public goods"}, {"id": "444aab0b-566d-4e62-b364-908a5f5d1037", "type": "concept", "title": "Immigration, refugees, borders, asylum, national responsibility, and moral luck of birth"}, {"id": "11500250-3e4c-4843-a850-b9752d35cf6b", "type": "concept", "title": "Public health ethics, vaccine allocation, scarcity, disability justice, care work, and social determinants"}], "description": "Students apply justice frameworks to global and domestic policy cases."}]}, {"id": "000d48dd-dada-4a85-8732-6e3a6f8ebf8f", "type": "topic", "title": "Political Theory Practice: Close Reading, Conceptual Analysis, Debate, and Philosophical Writing", "description": "The final section consolidates the craft of political theory. Students practice reading difficult texts, reconstructing arguments, debating charitably, and writing clear philosophical prose.", "children": [{"id": "a1a8994a-3eb5-414b-a43a-3f652031484e", "type": "subtopic", "title": "Close Reading and Textual Interpretation", "children": [{"id": "b1488987-76b2-4f8a-bb6d-8435b7793f51", "type": "concept", "title": "Thesis, key term, passage analysis, context, structure, ambiguity, and interpretive puzzle"}, {"id": "b1c154c6-5e26-45fe-84a4-c7beae460cb3", "type": "concept", "title": "Annotation, paraphrase, argument map, quotation integration, textual evidence, and charitable reconstruction"}, {"id": "0e9992ac-a5ba-40ac-a603-1436fe6162de", "type": "concept", "title": "Author's question, opponent, concept shift, historical context, translation issue, and genre"}, {"id": "bd4b0ae6-e69d-473f-8641-4e6d79f0d120", "type": "concept", "title": "Comparing passages, tracing concepts, and distinguishing exposition from evaluation"}], "description": "Students learn to slow down and make difficult texts usable."}, {"id": "d5ea3274-9c84-4b28-8f9d-af9a5196247f", "type": "subtopic", "title": "Debate, Objection, and Reply", "children": [{"id": "0065222c-22d9-4257-86f6-41acc28ccbfc", "type": "concept", "title": "Objection, reply, counterexample, reductio, distinction, concession, revision, and burden shifting"}, {"id": "a4d902ae-b0d3-42c9-809e-4a5624613287", "type": "concept", "title": "Steel-manning, principle testing, scope condition, value conflict, and institutional feasibility"}, {"id": "2078ea2d-149d-47d0-9e6d-d3078037f482", "type": "concept", "title": "Seminar discussion, structured debate, public reason, disagreement norms, and intellectual humility"}, {"id": "4aea9e8e-ff21-4aec-a6f0-1b3b769aa84a", "type": "concept", "title": "Avoiding straw man, false dilemma, ad hominem, equivocation, circular reasoning, and slippery slope misuse"}], "description": "Students practice philosophical conversation as disciplined disagreement."}, {"id": "6ed021da-65ea-4afd-9bc1-953a50227345", "type": "subtopic", "title": "Philosophical Writing and Research", "children": [{"id": "39737f01-410d-4984-893a-e182606755cb", "type": "concept", "title": "Thesis statement, roadmap, exposition, argument reconstruction, objection section, reply section, conclusion"}, {"id": "3dd2f0f5-704a-47dd-b29c-7871076fde01", "type": "concept", "title": "Primary sources, secondary sources, Stanford Encyclopedia of Philosophy, PhilPapers, citation practices, and bibliography"}, {"id": "96d30aac-b4bf-4c0e-877b-87fb5700a5c3", "type": "concept", "title": "Conceptual clarity, signposting, paragraph unity, transitions, and concise prose"}, {"id": "a5527af2-d48d-46e7-8bab-ffa2d72dee3c", "type": "concept", "title": "Final paper, policy-theory memo, applied case essay, presentation, and revision workflow"}], "description": "Students turn reading and discussion into clear written argument."}]}], "dbBacked": true}$pthjson$::jsonb,
