insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('1ac35df0-0ebc-49d4-8b71-6b058d0bd24c', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', null, 'topic'::public.curated_course_node_type, 'What Political Theory Is: Questions, Methods, and Normative Argument', 'This opening section gives students the toolkit for doing political theory rather than only memorizing thinkers. The focus is on asking better questions, reading arguments carefully, and distinguishing empirical, conceptual, normative, and critical claims.', 0),
  ('ab8f7049-3e4e-40b2-ab40-a19a718deb88', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', '1ac35df0-0ebc-49d4-8b71-6b058d0bd24c', 'subtopic'::public.curated_course_node_type, 'Core Questions and Concepts', 'Students learn the recurring questions that organize the field.', 0),
  ('1eaaecf6-68e9-4060-aa88-c7d51be8a807', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'ab8f7049-3e4e-40b2-ab40-a19a718deb88', 'concept'::public.curated_course_node_type, 'Justice, authority, legitimacy, liberty, equality, power, rights, sovereignty, citizenship, democracy', null, 0),
