  ('aa205d10-b5d3-48f8-9618-ddd904d84d6d', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'ab8f7049-3e4e-40b2-ab40-a19a718deb88', 'concept'::public.curated_course_node_type, 'State, civil society, market, community, nation, people, class, public, private, and common good', null, 2),
  ('04c505fd-c111-4e08-b9da-5d1f675ec002', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'ab8f7049-3e4e-40b2-ab40-a19a718deb88', 'concept'::public.curated_course_node_type, 'Descriptive claims, normative claims, conceptual claims, interpretive claims, and critical claims', null, 3),
  ('c2d1a96d-5c54-42b6-9c93-2ad20e233b60', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', '1ac35df0-0ebc-49d4-8b71-6b058d0bd24c', 'subtopic'::public.curated_course_node_type, 'Methods of Political Theory', 'Students learn how theorists build arguments from texts, concepts, cases, and institutions.', 1),
  ('7ec71982-9c8a-449e-89df-1ea2610e0e3e', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'c2d1a96d-5c54-42b6-9c93-2ad20e233b60', 'concept'::public.curated_course_node_type, 'Close reading, conceptual analysis, genealogy, ideology critique, reflective equilibrium, thought experiment', null, 0),
  ('3dc6a942-8d0e-499a-b925-03fb91e37b38', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'c2d1a96d-5c54-42b6-9c93-2ad20e233b60', 'concept'::public.curated_course_node_type, 'Textual context, historical context, authorial purpose, reception, canon formation, and contemporary application', null, 1),
  ('7c36d381-6d41-45dd-91e2-92a6b3e078d0', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'c2d1a96d-5c54-42b6-9c93-2ad20e233b60', 'concept'::public.curated_course_node_type, 'Primary text, secondary literature, exegesis, reconstruction, objection, reply, and argumentative charity', null, 2),
  ('0f76370b-b4ec-4108-9acb-a2db69be5f69', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'c2d1a96d-5c54-42b6-9c93-2ad20e233b60', 'concept'::public.curated_course_node_type, 'Analytic political philosophy, history of political thought, critical theory, comparative political theory, and applied theory', null, 3),
  ('ff2b7db7-50cd-4c57-819d-3bb1c3bb59ce', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', '1ac35df0-0ebc-49d4-8b71-6b058d0bd24c', 'subtopic'::public.curated_course_node_type, 'Normative Argument and Evaluation', 'Students practice evaluating claims about what political life should be like.', 2),
