  ('028241fe-a680-4274-a6e9-27033c0b2da6', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'ff2b7db7-50cd-4c57-819d-3bb1c3bb59ce', 'concept'::public.curated_course_node_type, 'Universalism, particularism, ideal theory, nonideal theory, utopia, realism, and transitional justice', null, 2),
  ('717f4130-315a-4d91-975e-5bf80808ccc7', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'ff2b7db7-50cd-4c57-819d-3bb1c3bb59ce', 'concept'::public.curated_course_node_type, 'Writing thesis statements, defining terms, using textual evidence, and responding to objections', null, 3),
  ('eb9db126-4554-4d7f-b6f7-19d5968fd11d', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', null, 'topic'::public.curated_course_node_type, 'Ancient Political Thought: Plato, Aristotle, Citizenship, Virtue, and Regime Types', 'Ancient political thought asks what kind of city and character make human flourishing possible. Students study justice, virtue, citizenship, education, and the dangers of corrupt regimes.', 1),
  ('6dbccf81-73a5-4ccc-99eb-2ea361612a1e', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'eb9db126-4554-4d7f-b6f7-19d5968fd11d', 'subtopic'::public.curated_course_node_type, 'Plato, Justice, and the Ideal City', 'Students read Plato as a theorist of justice, education, knowledge, and political degeneration.', 0),
