  ('2d4183a8-fdd3-4367-bddb-a96f4472d8ac', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'eb9db126-4554-4d7f-b6f7-19d5968fd11d', 'subtopic'::public.curated_course_node_type, 'Aristotle, Virtue, and Constitutionalism', 'Students learn Aristotle''s account of political life as rooted in human flourishing and practical judgment.', 1),
