  ('ed13c6d7-c4b8-4e23-915c-acfde8559d6b', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', '2d4183a8-fdd3-4367-bddb-a96f4472d8ac', 'concept'::public.curated_course_node_type, 'Golden mean, habituation, civic virtue, common advantage, and constitutional stability', null, 3),
