  ('24d211f7-d4e6-4f91-a3c9-af50a46bfbd6', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'd8796da9-4529-4137-bf2e-7dbb4f511fd1', 'concept'::public.curated_course_node_type, 'Virtue politics, elite rule, civic education, anti-democratic arguments, and contemporary echoes', null, 3),
  ('f464665d-65d3-493e-ab90-115d44299421', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', null, 'topic'::public.curated_course_node_type, 'Medieval and Theological Political Thought: Aquinas, Natural Law, Authority, and Conscience', 'This section shows how political authority was theorized in relation to divine law, moral order, and conscience. Students examine natural law, just rule, and the limits of obedience.', 2),
  ('cfbb950d-fa10-42a9-897e-87853678c402', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'f464665d-65d3-493e-ab90-115d44299421', 'subtopic'::public.curated_course_node_type, 'Natural Law and Moral Order', 'Students learn how natural law links reason, morality, and political authority.', 0),
