  ('459f8a4e-5dfa-4601-8cfa-b03bc805afc5', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'cfbb950d-fa10-42a9-897e-87853678c402', 'concept'::public.curated_course_node_type, 'Natural rights, natural duties, medieval constitutionalism, and later rights theories', null, 3),
  ('2ed35324-5d0f-4fa5-afb1-d72117c06d6a', 'f8a9b0c1-2d3e-4f58-9a78-8b9c0d1e2f08', 'f464665d-65d3-493e-ab90-115d44299421', 'subtopic'::public.curated_course_node_type, 'Church, State, and Political Authority', 'Students examine conflicts between temporal and spiritual power.', 1),
